1	/**
2	 * The whole screen: the launchpad, and the map you open from it.
3	 *
4	 * Two states and nothing in between. The launchpad offers four ways to start —
5	 * the stored map, the committed recording, a live run of one of the four
6	 * sentences from the brief, and a sentence of the reader's own; taking any of
7	 * them swaps the page for the map. Everything on the map came over the wire
8	 * from the server, and the line under it says which address it came from — this
9	 * product does not put a number on screen that a reader cannot trace to an
10	 * input, a rule or a source, and that includes numbers a stored example happens
11	 * to carry.
12	 *
13	 * There is no spinner anywhere, and there never will be. A spinner says "wait"
14	 * without saying what for. While something is on its way the screen says what
15	 * it is waiting for and where it asked.
16	 */
17	
18	import { useCallback, useEffect, useMemo, useState } from "react";
19	import type { About, FixtureSummary, Health, Readiness } from "./api/client";
20	import { readAbout, readExampleList, readHealth, readReadiness } from "./api/client";
21	import type { Asked } from "./components/InputBar";
22	import { Launchpad } from "./components/Launchpad";
23	import { MapScreen } from "./components/MapScreen";
24	import { GenerationScreen } from "./stream/GenerationScreen";
25	import type { TheRun } from "./stream/theRun";
26	import { askForAMap } from "./stream/theRun";
27	import {
28	  ApiWorldSource,
29	  type BranchView,
30	  branchesOf,
31	  FixtureWorldSource,
32	  type WorldSource,
33	  type WorldView,
34	} from "./world";
35	import { asOneSentence } from "./world/failures";
36	import { countInWords } from "./world/naming";
37	
38	/**
39	 * Everything the screen can know about one thing it asked for. Three states and
40	 * no others, which is what makes every pixel below traceable to a cause.
41	 */
42	type Answer<Reading> =
43	  | { state: "asking" }
44	  | { state: "answered"; value: Reading }
45	  | { state: "failed"; reason: string };
46	
47	/** How loud a row's words are. Emphasis only — the words carry the meaning. */
48	type Tone = "good" | "quiet" | "loud";
49	
50	/** One row of the strip at the foot of the launchpad. */
51	interface Reading {
52	  /** What is being reported, such as "server". */
53	  label: string;
54	  /** The value from the server, or null while the request is still in flight. */
55	  value: string | null;
56	  /** A mark beside the words. Never the only carrier of meaning. */
57	  glyph: string;
58	  /** What the value means, in plain words. On a failure, this is the failure. */
59	  state: string;
60	  tone: Tone;
61	}
62	
63	/**
64	 * Ask what this copy can do.
65	 *
66	 * Defined at module level because the hook below runs it once and needs the
67	 * same function on every render.
68	 *
69	 * **It reads the generated description of the server and nothing else.** The
70	 * two fields the first screen lives on — which examples can be played, and one
71	 * sentence per recording this engine could not read — were written out by hand
72	 * here for as long as the route that owns them was being built beside this
73	 * half. They are in `schema.ts` now, so the hand-written copy is gone: two
74	 * descriptions of one answer eventually disagree, and the generated one is the
75	 * server's own.
76	 */
77	function askReadiness(): Promise<Readiness> {
78	  return readReadiness();
79	}
80	
81	/**
82	 * Make one request when the screen first appears and report where it got to.
83	 *
84	 * @param ask The request to make. It must be the same function on every render,
85	 *   so pass one defined at module level rather than one written inline.
86	 */
87	function useAnswer<Reading>(ask: () => Promise<Reading>): Answer<Reading> {
88	  const [answer, setAnswer] = useState<Answer<Reading>>({ state: "asking" });
89	
90	  useEffect(() => {
91	    let stillOnScreen = true;
92	    ask().then(
93	      (value) => {
94	        if (stillOnScreen) {
95	          setAnswer({ state: "answered", value });
96	        }
97	      },
98	      (reason: unknown) => {
99	        if (stillOnScreen) {
100	          setAnswer({ state: "failed", reason: asOneSentence(reason) });
101	        }
102	      },
103	    );
104	    return () => {
105	      stillOnScreen = false;
106	    };
107	  }, [ask]);
108	
109	  return answer;
110	}
111	
112	/**
113	 * Whether the server answered, and which build answered — in one quiet line.
114	 *
115	 * **They were two rows of the strip, and they are two facts a reader of this
116	 * screen is not making a decision about.** A route name and a build number
117	 * under the first screen make a take-home read as an implementation showcase at
118	 * the moment it should read as a decision tool. Nothing is lost: both readings
119	 * are still here, still the server's own, still traceable to the address the
120	 * line under them names. They are simply not given the weight of a labelled row
121	 * beside the one reading that changes what a reader can do, which is whether
122	 * there is a model key.
123	 *
124	 * Each half says where it has got to for itself, so a failure of one is not
125	 * hidden by the other answering.
126	 *
127	 * @param health What `/api/healthz` said, or where that question has got to.
128	 * @param about What `/api/about` said, or where that question has got to.
129	 */
130	function serverAndBuild(health: Answer<Health>, about: Answer<About>): string {
131	  const reachable =
132	    health.state === "asking"
133	      ? "Asking the server whether it is there."
134	      : health.state === "answered"
135	        ? `Server ${health.value.status}.`
136	        : health.reason;
137	  const build =
138	    about.state === "asking"
139	      ? "Asking which build answered."
140	      : about.state === "answered"
141	        ? `Build ${about.value.version}, reported by ${about.value.name}.`
142	        : about.reason;
143	  return `${reachable} ${build}`;
144	}
145	
146	/** The row that says whether a key for the language model is configured. */
147	function modelKeyReading(answer: Answer<Readiness>): Reading {
148	  switch (answer.state) {
149	    case "asking":
150	      return {
151	        label: "model key",
152	        value: null,
153	        glyph: "○",
154	        state: "asking the server",
155	        tone: "quiet",
156	      };
157	    case "answered":
158	      return answer.value.model_key_present
159	        ? {
160	            label: "model key",
161	            value: "present",
162	            glyph: "●",
163	            state: "ready to generate",
164	            tone: "good",
165	          }
166	        : {
167	            label: "model key",
168	            value: "absent",
169	            glyph: "○",
170	            state:
171	              answer.value.replayable.length === 0
172	                ? "no key configured, and nothing recorded to play instead"
173	                : `no key configured — ${countInWords(answer.value.replayable.length)} ` +
174	                  `${answer.value.replayable.length === 1 ? "example plays" : "examples play"} ` +
175	                  `from recordings`,
176	            tone: "quiet",
177	          };
178	    case "failed":
179	      return { label: "model key", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
180	  }
181	}
182	
183	/**
184	 * One row: a label, the value the server gave, and what that value means.
185	 *
186	 * While the value is missing the cell holds a bar of the same height, so the
187	 * row does not change size when the answer arrives. There is no spinner: a bar
188	 * where the value will land says the same thing without pretending to spin.
189	 */
190	function StatusRow({ reading }: { reading: Reading }) {
191	  const waiting = reading.value === null;
192	  return (
193	    <div className="status-row">
194	      <dt className="status-label">{reading.label}</dt>
195	      <dd className="status-value" data-settled={waiting ? "no" : "yes"}>
196	        {waiting ? <span className="placeholder" aria-hidden="true" /> : reading.value}
197	      </dd>
198	      <dd className="status-state" data-tone={reading.tone}>
199	        <span className="glyph" aria-hidden="true">
200	          {reading.glyph}
201	        </span>
202	        <span className="state-words">{reading.state}</span>
203	      </dd>
204	    </div>
205	  );
206	}
207	
208	/** Which of the screens is showing. */
209	type Screen =
210	  | { at: "launchpad" }
211	  | { at: "opening"; id: string }
212	  /**
213	   * A map being built in front of the reader, from a sentence they typed.
214	   *
215	   * **The run is here, not inside the screen**, because the press that made this
216	   * state is what asked for it. A screen that asked on mount would ask twice in
217	   * development, where React mounts every screen, unmounts it and mounts it
218	   * again on purpose — and *"never retry, a generation that ran twice would
219	   * spend twice"* would be broken on every machine this product is built on.
220	   */
221	  | { at: "growing"; run: TheRun }
222	  | {
223	      at: "map";
224	      world: WorldView;
225	      branches: readonly BranchView[];
226	      /**
227	       * Why the map on screen was read from the stored example rather than
228	       * worked out by the engine, or nothing when the engine answered.
229	       */
230	      insteadOfTheEngine: string | null;
231	    }
232	  | { at: "failed"; id: string; reason: string };
233	
234	/**
235	 * Where maps come from: the engine.
236	 *
237	 * Every number on the map is worked out by it, from the stored map, the branch
238	 * and one seed. Nothing on this screen computes a likelihood, and nothing on
239	 * this screen shows one the engine did not produce.
240	 */
241	const DEFAULT_SOURCE: WorldSource = new ApiWorldSource();
242	
243	/**
244	 * Where maps come from when the engine cannot be reached.
245	 *
246	 * A map you can still read beats a blank screen. The stored example's claims,
247	 * arrows, dates and sources are all real and all still worth reading — what is
248	 * missing is the working-out, and the screen says so in a line under the map
249	 * rather than letting a hand-written likelihood pass for a computed one.
250	 */
251	const FALLBACK_SOURCE: WorldSource = new FixtureWorldSource();
252	
253	/**
254	 * The line under the map when the stored example is standing in for the engine.
255	 *
256	 * @param reason What went wrong, in the sentence the failure arrived with.
257	 */
258	function insteadOfTheEngine(reason: string): string {
259	  return (
260	    `The engine did not answer, so this map is the stored example exactly as it was written: ` +
261	    `its claims, arrows, dates and sources are real, and its likelihoods are the illustrative ` +
262	    `ones somebody wrote down rather than anything worked out. ${reason}`
263	  );
264	}
265	
266	/** What the screen needs. All three have defaults; all three exist so they can be swapped. */
267	export interface AppProps {
268	  /** Where maps and worlds come from. */
269	  readonly source?: WorldSource;
270	  /** Where they come from when the first one cannot answer. */
271	  readonly fallback?: WorldSource;
272	  /** How the list of stored examples is read. */
273	  readonly listExamples?: () => Promise<FixtureSummary[]>;
274	}
275	
276	/** The screen. */
277	export function App({
278	  source = DEFAULT_SOURCE,
279	  fallback = FALLBACK_SOURCE,
280	  listExamples = readExampleList,
281	}: AppProps = {}) {
282	  const health = useAnswer(readHealth);
283	  const readiness = useAnswer(askReadiness);
284	  const about = useAnswer(readAbout);
285	  const examples = useAnswer(listExamples);
286	
287	  const [screen, setScreen] = useState<Screen>({ at: "launchpad" });
288	  const [using, setUsing] = useState<WorldSource>(source);
289	
290	  const open = useCallback(
291	    (id: string) => {
292	      setScreen({ at: "opening", id });
293	      /**
294	       * The world and the map's own branches, together: the world is what gets
295	       * drawn, and the branches are the edits somebody already made to it, which
296	       * the panel lists and the diff view folds on.
297	       *
298	       * @param from Where to ask.
299	       */
300	      const ask = (from: WorldSource) =>
301	        Promise.all([from.readWorld({ baseId: id }), from.readBundle(id)]);
302	
303	      ask(source).then(
304	        ([world, bundle]) => {
305	          setUsing(source);
306	          setScreen({ at: "map", world, branches: branchesOf(bundle), insteadOfTheEngine: null });
307	        },
308	        (failure: unknown) => {
309	          // The engine could not answer. Rather than a blank screen, the stored
310	          // example — and a line under the map saying, in the failure's own
311	          // words, that these are not computed numbers.
312	          ask(fallback).then(
313	            ([world, bundle]) => {
314	              setUsing(fallback);
315	              setScreen({
316	                at: "map",
317	                world,
318	                branches: branchesOf(bundle),
319	                insteadOfTheEngine: insteadOfTheEngine(asOneSentence(failure)),
320	              });
321	            },
322	            // Neither answered, which means the server itself is not there. That
323	            // is one sentence on the page, and a way back to the launchpad.
324	            (alsoFailed: unknown) =>
325	              setScreen({ at: "failed", id, reason: asOneSentence(alsoFailed) }),
326	          );
327	        },
328	      );
329	    },
330	    [source, fallback],
331	  );
332	
333	  const toLaunchpad = useCallback(() => setScreen({ at: "launchpad" }), []);
334	
335	  /**
336	   * Build a map from a sentence, and watch it arrive.
337	   *
338	   * **The request goes from here**, inside the press. Not from a render and not
339	   * from an effect: an effect runs twice in development by design, and this is
340	   * the one request in the product where running twice means paying twice.
341	   */
342	  // **The reader says how the run starts, and this passes it on untouched**
343	  // (record 0012, amended 2026-09-21). The route used to read the key and
344	  // decide; then this expression stood in for it here. Now the first screen
345	  // offers the choice — *watch the recording* or *run it live* — and every press
346	  // that reaches this arrives with the start already named. Nothing between the
347	  // press and the request may change it: a screen that asked for a recording and
348	  // a request that called a model would be the one lie this product cannot
349	  // afford.
350	  const build = useCallback((asked: Asked) => {
351	    setScreen({ at: "growing", run: askForAMap(asked) });
352	  }, []);
353	
354	  /**
355	   * Leave a generation: let go of it first, then go back.
356	   *
357	   * Letting go is what stops the spending — the route checks whether the client
358	   * is still there before its next model call — and it is done here, in the
359	   * press, rather than when the screen unmounts, for the same reason the run is
360	   * started in a press: a development-mode unmount would stop a run nobody left.
361	   */
362	  const leaveTheRun = useCallback(
363	    (run: TheRun) => () => {
364	      run.letGo();
365	      setScreen({ at: "launchpad" });
366	    },
367	    [],
368	  );
369	
370	  /** Ask the same question again, which is a new run and a new screen. */
371	  const runAgain = useCallback(
372	    (run: TheRun) => () => {
373	      run.letGo();
374	      setScreen({ at: "growing", run: askForAMap(run.asked) });
375	    },
376	    [],
377	  );
378	
379	  // **One labelled row, and one quiet line.** The row is the model key, because
380	  // it is the one reading on this screen that changes what a reader can do — it
381	  // is why a sentence has a recording behind it or nothing at all. Whether the
382	  // server answered and which build answered are still here, in the line under
383	  // it, where they are traceable without being the first thing read.
384	  const readings = useMemo(() => [modelKeyReading(readiness)], [readiness]);
385	  const behind = useMemo(() => serverAndBuild(health, about), [health, about]);
386	
387	  if (screen.at === "growing") {
388	    return (
389	      <GenerationScreen
390	        // Named by the press that asked for it, so that asking the same question
391	        // again draws a fresh screen rather than a second map inside the first
392	        // one's selection and focus.
393	        key={screen.run.press}
394	        run={screen.run}
395	        // Known before the stream has said anything, which is the whole reason
396	        // the badge can be on screen from the first frame. **It is what was
397	        // asked for**, not what a key implies: with a key, a reader can still
398	        // ask for the recording, and the badge has to say so from the first
399	        // frame. When the receipt arrives it is the authority, and the badge
400	        // takes its word.
401	        replaying={screen.run.asked.start === "replay"}
402	        onRunAgain={runAgain(screen.run)}
403	        onLeave={leaveTheRun(screen.run)}
404	      />
405	    );
406	  }
407	
408	  if (screen.at === "map") {
409	    return (
410	      <MapScreen
411	        base={screen.world}
412	        branches={screen.branches}
413	        source={using}
414	        insteadOfTheEngine={screen.insteadOfTheEngine}
415	        onLeave={toLaunchpad}
416	      />
417	    );
418	  }
419	
420	  if (screen.at !== "launchpad") {
421	    return (
422	      <main className="page page--map">
423	        <header className="map-bar">
424	          <button className="map-bar__back" type="button" onClick={toLaunchpad}>
425	            <span aria-hidden="true">←</span> Back to the launchpad
426	          </button>
427	          <h1 className="map-bar__title">Strait of Hormuz</h1>
428	        </header>
429	
430	        <div className="map-waiting">
431	          <p className="map-waiting__line">
432	            {screen.at === "opening"
433	              ? `Reading the map from /api/fixtures/${screen.id} and asking /api/worlds to work ` +
434	                `its likelihoods through.`
435	              : screen.reason}
436	          </p>
437	        </div>
438	      </main>
439	    );
440	  }
441	
442	  return (
443	    <main className="page">
444	      {/* The first screen is the one wide column in this product: it holds four
445	          ways to start, one of them a form, and stacking all of that in the
446	          660-pixel measure the rest of the page reads at pushes the form below
447	          the fold. `launchpad.css` owns the width. */}
448	      <div className="column column--launchpad">
449	        <header className="masthead">
450	          <h1 className="wordmark">Katalyst</h1>
451	          <p className="purpose">
452	            Type an event you think will happen. Katalyst builds a map of what it would cause, step
453	            by step, out to things you could trade.
454	          </p>
455	        </header>
456	
457	        <Launchpad
458	          examples={examples.state === "answered" ? examples.value : null}
459	          failure={examples.state === "failed" ? examples.reason : null}
460	          readiness={readiness.state === "answered" ? readiness.value : null}
461	          // **An absent answer is two different facts and the screen is handed
462	          // both.** Without this, a readiness request that failed looked exactly
463	          // like one still in flight, and the first screen said *asking the
464	          // server* for ever over an ask that had ended — while the strip below
465	          // it printed the failure's own sentence. A screen asserting a question
466	          // that is not being asked is a state nobody can trace to an input.
467	          readinessFailure={readiness.state === "failed" ? readiness.reason : null}
468	          onOpen={open}
469	          onBuild={build}
470	        />
471	
472	        <section aria-labelledby="status-heading">
473	          <h2 className="section-heading" id="status-heading">
474	            What this build can do right now
475	          </h2>
476	          <dl className="status-strip">
477	            {readings.map((reading) => (
478	              <StatusRow key={reading.label} reading={reading} />
479	            ))}
480	          </dl>
481	          <p className="provenance">{behind}</p>
482	          <p className="provenance">
483	            Every reading above came from the server, at <code>/api/healthz</code>,{" "}
484	            <code>/api/readyz</code> and <code>/api/about</code>. The examples came from{" "}
485	            <code>/api/fixtures</code>. Nothing on this screen is written into the page.
486	          </p>
487	        </section>
488	      </div>
489	    </main>
490	  );
491	}
