1	/**
2	 * The screen a stored map is read and edited on.
3	 *
4	 * The map fills it, the panel beside it answers *why is this number what it
5	 * is*, and every edit a reader makes goes onto a branch of their own rather
6	 * than onto the map. Nothing here works a number out: the engine is asked for
7	 * the map with the branch folded on, and while it is being asked the slot says
8	 * so in words rather than showing a stale figure or a spinner.
9	 *
10	 * **The screen around the map is not here.** It is `MapFrame`, shared with the
11	 * map that builds itself: a bar with the way back, the stage, the panel in its
12	 * frame, one polite line said out loud and the origin strip at the foot. The
13	 * two screens were written twice and drifted the moment either was improved —
14	 * the panel's frame landed on one a round before the other, the error boundary
15	 * on one and never on the other.
16	 */
17	
18	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
19	import { branchAnnouncement } from "../a11y/announcement";
20	import { outlineOf } from "../a11y/sentences";
21	import { RefusedBranch } from "../api/client";
22	import { MapCanvas } from "../graph/Canvas";
