24	import { endings, NO_SUMMARY_YET } from "../graph/diff/endings";
25	import { roomFor } from "../graph/geometry";
26	import { useEveryKey } from "../keyboard/everyKey";
27	import type { MapKeys } from "../keyboard/useMapKeys";
28	import {
29	  type Absence,
30	  appendEdit,
31	  type BranchView,
32	  type DiffView,
33	  type Edit,
34	  forkBranch,
35	  type Known,
36	  type LinkView,
37	  openBranch,
38	  type Ranged,
39	  type Reason,
40	  type Selection,
41	  type WorldSource,
42	  type WorldView,
43	  workshopOf,
44	} from "../world";
45	import { absence } from "../world/absence";
46	import { asOneSentence } from "../world/failures";
47	import { BranchPanel, InterventionPanel } from "./BranchPanel";
48	import { type Command, CommandPalette } from "./CommandPalette";
49	import { DeltaRail } from "./DeltaRail";
50	import { Inspector } from "./Inspector";
51	import { MapFrame } from "./MapFrame";
52	import { Outline } from "./Outline";
53	import { type PanelChoice, PanelSwitch, theLabelFor } from "./PanelSwitch";
54	import { Refusal } from "./Refusal";
55	import { RunStrip } from "./RunStrip";
56	import { ShortcutsSheet } from "./ShortcutsSheet";
57	
58	/** How long the wires take to arrive, column by column, before the map settles. */
59	const WAVE_SETTLES_AFTER = 1200;
60	
61	/**
62	 * The three panels this screen has, by the name it keeps them under.
63	 *
64	 * **Three, because there are three things beside this map to read**: whatever
65	 * the reader has pointed at and the six things they can do to it, their
66	 * branches with everything the open one moved, and the map as a list. There is
67	 * no run here — nobody generated a stored map — so no panel offers one.
68	 *
69	 * All three used to be one column, with the branches and the change list
70	 * stacked above the answer to *why is this number what it is*. That is the
71	 * clutter Kent read as *"the side bar is pretty cluttered"*, and it is why a
72	 * click on a tile filled a box below the fold.
73	 */
74	type PanelName = "subject" | "branches" | "outline";
75	
76	/** What the line under the map says when the reader turns to each panel. */
77	const PANEL_IN_WORDS: Record<PanelName, string> = {
78	  subject: "the claim or arrow you are on, in the panel beside the map",
79	  branches: "your branches and what the open one moved",
80	  outline: "the map as a list",
81	};
82	
83	/**
84	 * What stands where a likelihood would go while the engine is being asked for
85	 * one.
86	 *
87	 * The shared vocabulary has three ways of saying a number is not there, and
88	 * this is the third of them — *nothing has been computed* — because that is
89	 * exactly what is true while a question is in flight: the engine has been asked
90	 * and has not answered, so nothing has worked this number through the map
91	 * **yet**. It is not a fourth kind of absence and it is not a spinner: the map
92	 * on screen keeps its shape, the slots that will move say why they are empty,
93	 * and the line under the map says what has been asked for and where.
94	 */
95	const WHILE_ASKING: Absence = absence(
96	  "no_engine",
97	  "The engine has been asked at /api/worlds for the map with this branch folded onto it, and " +
98	    "has not answered. Nothing has worked this number through the map yet.",
99	);
100	
101	/**
102	 * What stands where a likelihood would go when the engine **refused** the
103	 * branch.
104	 *
105	 * Not "no engine yet": the engine is there and it answered — it said the branch
106	 * does not fit the map, and it said why. The words have to be true of that, and
107	 * the vocabulary's first three rows are all about a number nobody has worked out
108	 * rather than one that could not be. So there is a **fourth row** — *the engine
109	 * refused the branch these numbers would come from* → **not worked out** — and a
110	 * kind of its own to go with it, because "nothing has run yet" invites waiting
111	 * and "the engine turned this down" invites repairing what it turned down.
112	 */
113	const REFUSED: Absence = absence(
114	  "refused",
115	  "The engine would not work this map out from this branch: the branch does not fit the map. " +
116	    "Every reason is beside the map, and nothing on the map has changed.",
117	);
118	
119	/**
120	 * What stands there when the engine could not be reached at all.
121	 *
122	 * **Not a refusal**, and the difference is the whole of why the two are separate
123	 * kinds. A refusal is an answer: the engine looked, said no, and said why, and
124	 * it will say the same thing until the branch is repaired. This is one attempt
125	 * that did not come back — the engine is there and it was asked — and it stops
126	 * being true the moment the reader asks again. So it takes the kind that is
127	 * never kept, and its reason says what to do about it.
128	 */
129	function unreachable(reason: string): Absence {
130	  return absence(
131	    "ask_failed",
132	    `${reason} Nothing on the map has changed; opening the branch again asks once more.`,
133	  );
134	}
135	
136	/**
137	 * Everything the engine has said about the branch that is open, and whether it
138	 * has said it yet.
139	 */
140	type Answered =
141	  | { at: "asking" }
142	  | { at: "answered"; computed: { now: WorldView; change: DiffView } }
143	  | { at: "refused"; reasons: readonly Reason[] }
144	  | { at: "failed"; reason: string }
145	  | { at: "nothing-open" };
146	
147	/**
148	 * Where the engine has got to, in the one shape the picture reads.
149	 *
150	 * Every state but *nothing is open* reserves the room an answer will take and
151	 * says why it is not there yet, so the map is the same size before and after the
152	 * answer lands and nothing on it jumps.
153	 */
154	function engineState(answer: Answered): Engine | undefined {
155	  switch (answer.at) {
156	    case "answered":
157	      return { at: "answered", now: answer.computed.now, change: answer.computed.change };
158	    case "asking":
159	      return { at: "waiting", absence: WHILE_ASKING };
160	    case "refused":
161	      return { at: "waiting", absence: REFUSED };
162	    case "failed":
163	      return { at: "waiting", absence: unreachable(answer.reason) };
164	    case "nothing-open":
165	      return undefined;
166	  }
167	}
168	
169	/** Turn whatever the engine threw into either a list of reasons or one sentence. */
170	function asAnswer(reason: unknown): Answered {
171	  if (reason instanceof RefusedBranch) {
172	    return { at: "refused", reasons: reason.reasons };
173	  }
174	  return { at: "failed", reason: asOneSentence(reason) };
175	}
176	
177	/**
178	 * The map, the panel beside it, and everything you can do to both.
179	 *
180	 * Three things live here rather than inside the map, because all three are about
181	 * the whole screen rather than about the picture: which branch is open, which of
182	 * the two worlds is painted, and what the keyboard is on.
183	 */
184	export function MapScreen({
185	  base,
186	  branches,
187	  source,
188	  insteadOfTheEngine,
189	  onLeave,
190	}: {
191	  base: WorldView;
192	  branches: readonly BranchView[];
193	  /** Where a branch's world, its difference and an arrow's number are asked for. */
194	  source: WorldSource;
195	  /** Why this map is the stored example rather than the engine's, or nothing. */
196	  insteadOfTheEngine: string | null;
197	  onLeave: () => void;
198	}) {
