200	  const [showing, setShowing] = useState<"now" | "before">("now");
201	  const [selection, setSelection] = useState<Selection>(null);
202	  const [focused, setFocused] = useState<string | null>(null);
203	  // Which of this screen's three panels is on the glass. It opens on the one
204	  // that says what to do next — *choose a claim or an arrow on the map* — which
205	  // is the sentence a reader who has never seen this screen needs first.
206	  const [dock, setDock] = useState<PanelName>("subject");
207	  // And whether the panel is there at all. `P` puts it away and gives the map
208	  // the whole width; it is a fact about the panel rather than about which of
209	  // them is showing, so it is kept apart from the three.
210	  const [away, setAway] = useState(false);
211	  const [onlyColumn, setOnlyColumn] = useState<{
212	    layer: number;
213	    claims: readonly string[];
214	  } | null>(null);
215	  const [overlay, setOverlay] = useState<"palette" | "sheet" | null>(null);
216	  const [intervening, setIntervening] = useState(false);
217	  const [naming, setNaming] = useState(false);
218	  const [status, setStatus] = useState(
219	    "Press ? for every key. j and k walk a column; h and l follow the wires.",
220	  );
221	  const [arriving, setArriving] = useState(true);
222	  const lastBranch = useRef<string | null>(null);
223	
224	  const open = shop.branches.find((branch) => branch.id === shop.openId);
225	
226	  // What the engine says about the branch that is open. It is asked again
227	  // whenever the branch changes — which is what makes the six buttons move
228	  // numbers: pressing one appends an edit, and the whole branch goes back.
229	  const [answer, setAnswer] = useState<Answered>({ at: "nothing-open" });
230	  // How many times the engine has been asked, so that the strip's reading of
231	  // how long this question has been out starts again with each one.
232	  const [asks, setAsks] = useState(0);
233	  useEffect(() => {
234	    if (open === undefined) {
235	      setAnswer({ at: "nothing-open" });
236	      return;
237	    }
238	    let stillWanted = true;
239	    setAnswer({ at: "asking" });
240	    // One more question has gone out. The strip at the foot starts its count of
241	    // seconds again from here — this is the only thing that count is for, and it
242	    // is a count of questions asked, never of anything on the map.
243	    setAsks((many) => many + 1);
244	    Promise.all([
245	      source.readWorld({ baseId: base.baseId, branch: open }),
246	      source.readDiff({ baseId: base.baseId, branch: open }),
247	    ]).then(
248	      ([now, change]) => {
249	        if (stillWanted) {
250	          setAnswer({ at: "answered", computed: { now, change } });
251	        }
252	      },
253	      (failure: unknown) => {
254	        if (stillWanted) {
255	          setAnswer(asAnswer(failure));
256	        }
257	      },
258	    );
259	    return () => {
260	      // An answer to a question the reader has moved on from is thrown away
261	      // rather than drawn: a map that flickers back to an older branch because
262	      // a slower request finished last is a map nobody can trust.
263	      stillWanted = false;
264	    };
265	    // The branch itself is what this hangs on, and that is enough: appending an
266	    // edit hands back a new branch rather than changing the one that was there
267	    // — a branch is an audit trail and nothing rewrites one — so every press of
268	    // a button is a new question here, and nothing else is.
269	  }, [source, base.baseId, open]);
270	
271	  // Held still between renders, because both paintings of the map hang on it: a
272	  // fresh object every render would lay the whole map out again on every keypress
273	  // for an answer that has not changed.
274	  const engine = useMemo(() => engineState(answer), [answer]);
275	  const computed = answer.at === "answered" ? answer.computed : undefined;
276	
277	  // The numbers on the arrows, one at a time, kept once they arrive. Each one
