868	          {insteadOfTheEngine === null ? null : (
869	            <p className="map-origin__line">{insteadOfTheEngine}</p>
870	          )}
871	          {(world.warnings ?? []).map((warning) => (
872	            <p className="map-origin__line" key={warning}>
873	              {warning}
874	            </p>
875	          ))}
876	        </>
877	      }
878	    />
879	  );
880	}
