1	/**
2	 * The screen a map builds itself on.
3	 *
4	 * The same canvas, the same panel and the same keyboard as every other map. What
5	 * is different is where the map comes from: it arrives claim by claim down one
6	 * request, with a reserved rectangle standing wherever the next one will go, and
7	 * every proposal the rules refused listed beside it.
8	 *
9	 * **There is no spinner here, and no moment where a blank screen turns into a
10	 * finished picture.** The growing *is* the loading state.
11	 *
12	 * **This screen does not ask for the map.** The press that opened it did
13	 * (`theRun.ts`), and this watches what that press started. It can be mounted,
14	 * unmounted and mounted again — which React's development mode does on purpose —
15	 * without a second generation being asked for, because there is no code here
16	 * that could ask for one.
17	 */
18	
19	import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from "react";
20	import { outlineOf } from "../a11y/sentences";
21	import { AddAClaim } from "../components/AddAClaim";
22	import { type Command, CommandPalette } from "../components/CommandPalette";
23	import { DoneLine } from "../components/DoneLine";
24	import { Inspector } from "../components/Inspector";
25	import { MapFrame } from "../components/MapFrame";
26	import { Outline } from "../components/Outline";
27	import { type PanelChoice, PanelSwitch, theLabelFor } from "../components/PanelSwitch";
28	import { ReceiptStrip } from "../components/ReceiptStrip";
29	import { RefusalStrip } from "../components/RefusalStrip";
30	import { ReplayBadge, replaySentence } from "../components/ReplayBadge";
31	import { RunStrip } from "../components/RunStrip";
32	import { ShortcutsSheet } from "../components/ShortcutsSheet";
33	import { VerdictCard } from "../components/VerdictCard";
34	import { MapCanvas } from "../graph/Canvas";
35	import { useEveryKey } from "../keyboard/everyKey";
36	import type { MapKeys } from "../keyboard/useMapKeys";
37	import type { Selection } from "../world";
38	import type { Growth, Phase } from "./growth";
39	import { hasStopped, onlyTheStripChanged } from "./growth";
40	import type { TheRun, WhereItHasGot } from "./theRun";
41	import type { Working } from "./transcript";
42	import { readTranscript } from "./transcript";
43	import "../components/generationDock.css";
44	
45	/**
46	 * Watch a run that is already going.
47	 *
48	 * `useSyncExternalStore` is React's own way of reading something that lives
49	 * outside React and changes on its own, and it is the right one here for a
50	 * reason that matters: subscribing and unsubscribing does nothing to the run.
51	 * A hook that *started* the generation would start two of them in development,
52	 * and *"never retry, a generation that ran twice would spend twice"* would be
53	 * broken on every machine where the app is developed.
54	 *
55	 * @param run The generation the press created.
56	 */
57	function useTheRun(run: TheRun): WhereItHasGot {
58	  return useSyncExternalStore(run.watch, run.now, run.now);
59	}
60	
61	/**
62	 * The state of the run, as the one word the strip puts in front of its
63	 * sentence.
64	 *
65	 * Six phases and seven words, because *live* and *replay* are the same phase
66	 * seen two ways and the difference matters to a reader: one is spending money
67	 * and taking a minute a call, the other is a recording being played back.
68	 *
69	 * @param phase Where the run has got to.
70	 * @param replaying True when this copy has no model key and is playing a
71	 *   recording back.
72	 */
73	export function theWordFor(phase: Phase, replaying: boolean): string {
74	  switch (phase) {
75	    case "waiting":
76	    case "growing":
77	      return replaying ? "replay" : "live";
78	    // A cap stopping a run and a run reaching its own end are both a finished
79	    // map: the map is on screen, nothing more is coming, and *why* is the
80	    // sentence beside the word rather than the word itself.
81	    case "settled":
82	    case "stopped":
83	      return "finished";
84	    case "failed":
85	      return "stopped";
86	    case "ended_early":
87	      return "ended early";
88	  }
89	}
90	
91	/**
92	 * The three panels this screen has, by the name it keeps them under.
93	 *
94	 * **Three, because there are three things beside this map to read**: whatever
95	 * the reader has pointed at, the run that is building it, and the map as a list.
96	 * There is no fourth: a generated map has no branches to open, so no panel
97	 * offers any. What this screen used to do was stack the first two in one column
98	 * with the run's half on top, so a click on a tile filled the bottom of a panel
99	 * nobody could see the bottom of.
100	 */
101	type PanelName = "subject" | "run" | "outline";
102	
103	/** What the line under the map says when the reader turns to each panel. */
104	const PANEL_IN_WORDS: Record<PanelName, string> = {
105	  subject: "the claim or arrow you are on, in the panel beside the map",
106	  run: "what this run is doing, in the panel beside the map",
107	  outline: "the map as a list",
108	};
109	
110	/** What the screen needs. */
111	export interface GenerationScreenProps {
112	  /** The run, already asked for by the press that opened this screen. */
113	  readonly run: TheRun;
114	  /**
115	   * True when the reader asked for the recording, so the run is one being played
116	   * back — whether or not this copy has a model key. Known before the stream
117	   * says anything, which is why the badge can be
118	   * on screen from the first frame — and why the offer to run it again can say
119	   * truthfully whether pressing it spends money.
120	   */
121	  readonly replaying: boolean;
122	  /** Ask for the same sentence again. A press, like the first one. */
123	  readonly onRunAgain: () => void;
124	  /** Let go of this run and go back. A press, and the only way off this screen. */
125	  readonly onLeave: () => void;
126	}
127	
128	/** A map building itself, and the panel beside it. */
129	export function GenerationScreen({ run, replaying, onRunAgain, onLeave }: GenerationScreenProps) {
130	  const { growth, saying } = useTheRun(run);
131	  const [selection, setSelection] = useState<Selection>(null);
132	  const [focused, setFocused] = useState<string | null>(null);
133	  const [overlay, setOverlay] = useState<"sheet" | "palette" | null>(null);
134	  // Which of this screen's three panels is on the glass. It opens on the run,
135	  // because at that moment the run is the only thing there is to read: nothing
136	  // is selected and there is no map yet.
137	  const [dock, setDock] = useState<PanelName>("run");
138	  const [openAt, setOpenAt] = useState<number | null>(null);
139	  const [status, setStatus] = useState(
140	    "Press ? for every key. j and k walk a column; h and l follow the wires.",
141	  );
142	  const [working, setWorking] = useState<Working>({ state: "reading" });
143	
144	  const { generationId, phase } = growth;
145	  const finished = hasStopped(phase);
146	
147	  // **How many events have arrived**, so the strip at the foot knows when to
148	  // start counting the silence again.
149	  //
150	  // It counts the run's own state being replaced, which is one for one with an
151	  // event arriving: `fold` hands back a new state for every one of the eight
152	  // events a recording holds, so a new object here is something having landed.
153	  //
154	  // **The ninth is not an arrival, and that is a decision rather than an
155	  // oversight** *(2026-09-22)*. An `activity` line is the model saying what it
156	  // is doing inside a call that has not come back; it reaches the strip and
157	  // nothing else. A counter that started again on each of them would read
158	  // *nothing new on the map for 1 s* for three solid minutes while nothing
159	  // whatever reached the map. The lines say the tool is alive by changing in
160	  // front of the reader; the number says how long this call has been out.
161	  //
162	  // **It is a count of arrivals and nothing else, and it is never drawn.**
163	  // The browser can count what it was sent; it cannot count the model's calls,
164	  // and must never print a number as if it could.
165	  const [arrivals, setArrivals] = useState(0);
166	  const lastSeen = useRef<Growth | null>(null);
167	  useEffect(() => {
168	    const before = lastSeen.current;
169	    lastSeen.current = growth;
170	    if (before === growth || onlyTheStripChanged(before, growth)) {
171	      return;
172	    }
173	    setArrivals((many) => many + 1);
174	  }, [growth]);
175	
176	  // The same three keys as every other screen, from the one module that binds
177	  // them — this screen prints *Press ? for every key* under the map, and until
178	  // that module existed the press did nothing here.
179	  useEveryKey({
180	    everyKey: () => setOverlay((was) => (was === "sheet" ? null : "sheet")),
181	    palette: () => setOverlay((was) => (was === "palette" ? null : "palette")),
182	    escape: () => setOverlay(null),
183	  });
184	
185	  // The working of the run, read once the run has finished. It is asked for then
186	  // rather than as it goes, because the server writes it from the same pass that
187	  // writes the stream and a half-read one would be a second, staler copy.
188	  //
189	  // **A run that ended early has a working too**, and it is the one case where
190	  // reading it back matters most: it is the only record of how far the run got.
191	  useEffect(() => {
192	    if (generationId === null || !finished) {
193	      return;
194	    }
195	    let stillWanted = true;
196	    readTranscript(generationId).then(
197	      (read) => {
198	        if (stillWanted) {
199	          setWorking(read);
200	        }
201	      },
202	      // `readTranscript` answers rather than throws, for every failure it can
203	      // name. This is for the ones it cannot: a screen that waits for a promise
204	      // that will never settle says *Reading the working…* until the tab closes.
205	      () => {
206	        if (stillWanted) {
207	          setWorking({
208	            state: "gone",
209	            reason: "The working of this run could not be read, and nothing said why.",
210	          });
211	        }
212	      },
213	    );
214	    return () => {
215	      stillWanted = false;
216	    };
217	  }, [generationId, finished]);
218	
219	  const outline = useMemo(() => outlineOf(growth.world), [growth.world]);
220	
221	  // The keyboard follows the growing edge: a claim that has just arrived takes
222	  // focus, exactly as a claim a branch adds does. That is what keeps the newest
223	  // tile on the glass through a run that goes on for minutes — the canvas
224	  // already brings whatever the keyboard is on into view, so nothing here
225	  // re-frames the map and nothing re-lays it out. A tile that is already placed
226	  // stays exactly where it is; what moves is where the reader is looking.
227	  //
228	  // A claim that has just **arrived** takes focus, and nothing else does. The
229	  // count is what says one arrived: when the likelihoods land, the engine's own
230	  // world replaces the drawing and its claims come back in the map's order
231	  // rather than the order they were proposed in — which is not an arrival, and
232	  // moving the view for it would slide the map sideways at the very moment it
233	  // stopped changing.
234	  const howManyClaims = growth.world.claims.length;
235	  const seenSoFar = useRef(0);
236	  const lastArrived = useRef<string | null>(null);
237	  useEffect(() => {
238	    if (howManyClaims <= seenSoFar.current) {
239	      return;
240	    }
241	    seenSoFar.current = howManyClaims;
242	    const arrived = growth.world.claims[howManyClaims - 1]?.id ?? null;
243	    lastArrived.current = arrived;
244	    setFocused(arrived);
245	  }, [howManyClaims, growth.world.claims]);
246	
247	  // And it lets go the moment the run stops. Focus is also what the hover lens
248	  // reads, and a lens left on a claim the machine chose would dim the whole
249	  // finished map to fifteen per cent at exactly the moment the reader starts
250	  // reading it. If the reader has moved since, their focus is theirs and stays.
251	  useEffect(() => {
252	    if (!finished) {
253	      return;
254	    }
255	    setFocused((was) => (was === lastArrived.current ? null : was));
256	  }, [finished]);
257	
258	  const pick = useCallback((id: string) => {
259	    setFocused(id);
260	    setSelection({ kind: "claim", id });
261	  }, []);
262	
263	  // **Choosing something is the one thing that moves the panel on its own.**
264	  //
265	  // Pointing at a tile or an arrow, or reaching one with the keyboard, puts what
266	  // you chose at the top of the panel at once — which is the whole of what was
267	  // wrong before: the click did select the tile, and the answer arrived at the
268	  // bottom of a column nothing scrolled.
269	  //
270	  // It follows the selection **object** rather than what is in it, because a
271	  // second press on the same tile is a second act of the reader's and must land
272	  // them back on what they asked for. Nothing else here ever calls for a panel:
273	  // a refusal arriving, the verdict landing and the receipt coming back all
274	  // change a panel the reader may not be looking at, and each of them says so on
275	  // that panel's own label and in the strip at the foot.
276	  const lastChosen = useRef(selection);
277	  useEffect(() => {
278	    if (selection === lastChosen.current) {
279	      return;
280	    }
281	    lastChosen.current = selection;
282	    if (selection === null) {
283	      return;
284	    }
285	    setDock(selection.kind === "generation" ? "run" : "subject");
286	  }, [selection]);
287	
288	  // Nothing on this screen is bound to the map's own six operations yet, so the
289	  // keys that open them say so rather than doing nothing.
290	  /**
291	   * Every command this screen has, by name.
292	   *
293	   * **It is a screen's own list, not a copy of the stored map's.** A generated
294	   * map has no branches to open and none of the six things you can do to a
295	   * claim, so offering them here would be a palette full of commands that
296	   * explain why they cannot run. What it does have is the four ways around it
297	   * and the two things it can do, and each one is also a key or a control on
298	   * the screen — which is the palette's whole promise.
299	   *
300	   * Before this, ⌘K on this screen opened the shortcuts sheet: a key that
301	   * silently does something else is the one thing this product's keyboard is
302	   * not allowed to do.
303	   */
304	  const commands: Command[] = useMemo(
305	    () => [
306	      {
307	        name: "Read the map as a list",
308	        does: "The same as pressing O. Every claim, one sentence each, in the order they arrived.",
309	        run: () => {
310	          setDock("outline");
311	          setStatus(PANEL_IN_WORDS.outline);
312	        },
313	      },
314	      {
315	        name: "Read what this run is doing",
316	        does: "What it refused, what it cost, and where it came from. Also a name at the head of the panel.",
317	        run: () => {
318	          setDock("run");
319	          setStatus(PANEL_IN_WORDS.run);
320	        },
321	      },
322	      // **Only once there is a working.** It is read back from the server when
323	      // the run stops, so a press before then leaves the panel saying *Reading
324	      // the working of this run…* until the run ends — a command that appears to
325	      // do nothing for two minutes.
326	      ...(generationId === null || !finished
327	        ? []
328	        : [
329	            {
330	              name: "Read the working of this run",
331	              does: "Every call it made, in order. The same as the control in the panel.",
332	              run: () => {
333	                setOpenAt(null);
334	                setSelection({ kind: "generation", id: generationId });
335	              },
336	            },
337	          ]),
338	      {
339	        name: "Every key",
340	        does: "The sheet of every key on this map. The same as pressing ?.",
341	        run: () => setOverlay("sheet"),
342	      },
343	      {
344	        name: "Back to the launchpad",
345	        does: "Let this run go and start again. The same as the control at the top left.",
346	        run: onLeave,
347	      },
348	    ],
349	    [generationId, finished, onLeave],
350	  );
351	
352	  const keys: MapKeys = useMemo(
353	    () => ({
354	      intervene: () => setStatus("a generated map takes edits through Add a claim, beside the map"),
355	      branch: () => setStatus("a branch is started on a stored map; this one is still being built"),
356	      flipWorlds: () => setStatus("there is nothing to flip to — no branch is open"),
357	      outline: () =>
358	        setDock((was) => {
359	          const next: PanelName = was === "outline" ? "subject" : "outline";
360	          setStatus(PANEL_IN_WORDS[next]);
361	          return next;
362	        }),
363	      panel: () => setStatus("the panel is beside the map · press N for the next one"),
364	      palette: () => setOverlay("palette"),
365	    }),
366	    [],
367	  );
368	
369	  /**
370	   * The three panels, and what each one's name carries beside it.
371	   *
372	   * **The name follows the subject** — *This claim* or *This arrow* — because
373	   * the name is what says what the panel is about, and an arrow is not a claim.
374	   *
375	   * **The count is read off the run, never written down.** It is how many
376	   * proposals the rules refused, which is the length of the list the panel
377	   * itself prints — so a reader who is on another panel is told the same number
378	   * they would count by hand, and told it without being pulled off what they
379	   * were reading.
380	   */
381	  const panels: readonly PanelChoice[] = useMemo(
382	    () => [
383	      { name: "subject", label: selection?.kind === "wire" ? "This arrow" : "This claim" },
384	      {
385	        name: "run",
386	        label: "The run",
387	        ...(growth.refusals.length === 0 ? {} : { mark: `refused ${growth.refusals.length}` }),
388	      },
389	      { name: "outline", label: "Outline" },
390	    ],
391	    [selection, growth.refusals.length],
392	  );
393	
394	  const turnTo = useCallback((name: string) => {
395	    const to = name as PanelName;
396	    setDock(to);
397	    setStatus(PANEL_IN_WORDS[to]);
398	  }, []);
399	
400	  return (
401	    <MapFrame
402	      title={growth.world.title}
403	      onLeave={onLeave}
404	      onEveryKey={() => setOverlay("sheet")}
405	      where={
406	        <p className="map-bar__where">
407	          {/* Nothing sits over the map: the mark that says this run is a
408	              recording is a badge up here, and the sentence explaining it is in
409	              the line under the map with every other sentence about where this
410	              map came from. */}
411	          {replaying ? (
412	            <ReplayBadge
413	              recordingDate={growth.receipt?.recording_date ?? null}
414	              receiptMode={growth.receipt?.mode ?? null}
415	            />
416	          ) : null}
417	          {run.asked.target === null ? "Explore" : "Verify"}
418	          <span className="map-bar__side">
419	            {run.asked.target === null ? "what your sentence would cause" : run.asked.target}
420	          </span>
421	        </p>
422	      }
423	      map={
424	        <MapCanvas
425	          world={growth.world}
426	          selection={selection}
427	          onSelect={setSelection}
428	          focused={focused}
429	          onFocused={setFocused}
430	          mapKey={generationId ?? "a run that has not started"}
431	          keys={keys}
432	          onStatus={setStatus}
433	          onOverflow={() => setStatus("every claim is in the list beside the map")}
434	          arriving={!finished}
435	          reserved={growth.skeletons}
436	          // Framed once when the first rectangle is drawn, and once more when
437	          // the run stops — the one moment nothing on the map is moving and the
438	          // reader is about to start reading it.
439	          frameAgainOn={finished ? "the run stopped" : undefined}
440	        />
441	      }
442	      overlay={
443	        <>
444	          {overlay === "palette" ? (
445	            <CommandPalette open={true} onClose={() => setOverlay(null)} commands={commands} />
446	          ) : null}
447	          {overlay === "sheet" ? (
448	            <ShortcutsSheet open={true} onClose={() => setOverlay(null)} />
449	          ) : null}
450	        </>
451	      }
452	      status={status}
453	      // The one strip that says what this run is doing: the state as a word,
454	      // the run's own sentence — said out loud and printed, one element so the
455	      // two cannot drift — and, only on a live run that is still open, how long
456	      // it has been since anything arrived.
457	      strip={
458	        <RunStrip
459	          word={theWordFor(phase, replaying)}
460	          saying={saying}
461	          // **A replay counts no seconds, and neither does a run that has
462	          // stopped.** A replay is paced by the server at six tenths of a
463	          // second an event, so the reading would reset twice a second and
464	          // would be measuring our own pacing rather than any wait.
465	          arrivals={replaying || finished ? null : arrivals}
466	          // **And the same rule for what the model is doing.** A recording
467	          // holds no such line, so a replay has none to show; a run that has
468	          // stopped has nothing out. Only a live run that is still open is
469	          // given them, and then the room for both is held open whether or not
470	          // either has anything in it yet.
471	          doing={replaying || finished ? null : growth.activity}
472	          after={
473	            <DoneLine
474	              done={growth.done}
475	              failure={growth.failure}
476	              endedEarly={phase === "ended_early"}
477	              // The offer is made only where there is something to offer: a
478	              // stream that stopped without saying why. A run that finished has
479	              // its map on screen, and a button asking whether to spend it all
480	              // again would be a control looking for a reason to exist.
481	              runAgain={
482	                phase === "ended_early" ? { costsMoney: !replaying, go: onRunAgain } : undefined
483	              }
484	            />
485	          }
486	        />
487	      }
488	      // The names of the three panels, at the head of the panel and outside the
489	      // part of it that scrolls, so the way to the other two is always on the
490	      // glass. This is the whole answer to *how do I know what panels exist*.
491	      panelHead={<PanelSwitch panels={panels} showing={dock} onShow={turnTo} />}
492	      panelNamedBy={theLabelFor(dock)}
493	      panel={
494	        /* The map as a list, in place of the panel, exactly as it is on a
495	           stored map: press O for it, press O again for the panel. It grows as
496	           the map grows, in the same causal order, so a reader who never sees
497	           the canvas hears the map being built rather than a silence followed
498	           by a finished list. */
499	        dock === "outline" ? (
500	          <Outline items={outline} onPick={pick} focused={focused} />
501	        ) : dock === "subject" ? (
502	          /* Whatever the reader pointed at, and nothing else in front of it.
503	             **This is the fix.** The panel used to be one column with the run's
504	             own sections stacked above this one, so a click on a tile filled the
505	             bottom of a box nothing scrolled — the answer arrived and the click
506	             looked dead. The run is a panel of its own now, one name away. */
507	          <Inspector world={growth.world} selection={selection} />
508	        ) : (
509	          <>
510	            {/* The Verify door's answer, at the top, when a destination was named. */}
511	            {growth.verdict === null || run.asked.target === null ? null : (
512	              <VerdictCard
513	                verdict={growth.verdict}
514	                target={run.asked.target}
515	                world={growth.world}
516	                onSelect={pick}
517	              />
518	            )}
519	
520	            <RefusalStrip
521	              refusals={growth.refusals}
522	              finished={finished}
523	              openAt={openAt}
524	              onOpen={(at) => {
525	                setOpenAt(at);
526	                setSelection({ kind: "generation", id: generationId ?? "" });
527	              }}
528	            />
529	
530	            {growth.receipt === null ? null : <ReceiptStrip receipt={growth.receipt} />}
531	
532	            {/* **One way into the working that is always there.**
533	                The panel's view of the run used to be reachable only from a
534	                refusal row or from the receipt strip's link — so a run that
535	                refused nothing had one way in, and only at the end, and a run
536	                whose stream was cut had none at all. That last one is the worst
537	                of the three: the working is the only record of how far a cut
538	                run got, the screen fetches it for exactly that reason, and then
539	                offered the reader no way to read it.
540	
541	                **And it appears only once there is a working.** It used to be
542	                drawn from the run's first event, while the thing it opens is
543	                read back from the server only when the run stops — so pressing
544	                it during the two minutes a reader is most likely to press it
545	                left the panel saying *Reading the working of this run…* until
546	                the run ended. A control that cannot do what it says is worse
547	                than no control. */}
548	            {generationId === null || !finished ? null : (
549	              <section className="generation-working" aria-label="The working of this run">
550	                <button
551	                  className="generation-working__open"
552	                  type="button"
553	                  onClick={() => {
554	                    setOpenAt(null);
555	                    setSelection({ kind: "generation", id: generationId });
556	                  }}
557	                >
558	                  Read the working of this run <span aria-hidden="true">→</span>
559	                </button>
560	              </section>
561	            )}
562	
563	            {finished && growth.world.baseId !== "" ? (
564	              // The same control, the same words and the same refusals as the
565	              // one on a stored map's six-button panel. What differs is only
566	              // what happens next: a generated map has no branch panel on this
567	              // screen yet, so the claim is drafted, checked and said, and
568	              // putting it on a branch of this map is the next piece of work.
569	              // No branch is sent because there is none to send.
570	              //
571	              // **It waits for the map to have a name of its own**, which is the
572	              // engine's `base_id` arriving with the likelihoods. A run that
573	              // broke or whose stream was dropped never gets one, and offering
574	              // to add a claim to a map that has no identifier would send the
575	              // *run's* name to a route that asks for the map's.
576	              //
577	              // **It is on this panel rather than on a name of its own**, at the
578	              // end of what the run did, because a panel is a place and this is
579	              // an act. It is the one thing here judged rather than derived, and
580	              // it is the first thing to move if Kent reads it the other way.
581	              <AddAClaim
582	                baseId={growth.world.baseId}
583	                andThen="It is checked against this map and ready to go onto a branch of it."
584	              />
585	            ) : null}
586	
587	            {/* Where this map is coming from, and — once the reader asks for it
588	                — every call the run made. **This panel is only ever about the
589	                run**, so it is handed the run's own selection and nothing else:
590	                a claim the reader chose is read out on its own panel, one name
591	                away, and reading it here as well would be one answer printed in
592	                two places. */}
593	            <Inspector
594	              world={growth.world}
595	              about="the run"
596	              selection={selection?.kind === "generation" ? selection : null}
597	              generation={{
598	                generationId,
599	                seed: growth.seed,
600	                promptFingerprint: growth.receipt?.prompt_hash ?? null,
601	                working,
602	                unknown: growth.unknown,
603	                openAt,
604	              }}
605	            />
606	          </>
607	        )
608	      }
609	      origin={
610	        <>
611	          {/* **Where this map came from is not here any more.** The route, the
612	              run's own name, the seed and the map's own origin sentence are all
613	              read in *Run details*, in the panel — R16, brought forward. The
614	              line that stood here said *"Every claim and arrow on this map
615	              arrived from…"* from the run's first event, which is to say over a
616	              map with nothing on it yet, and it was the third of three stacked
617	              strips of prose at the foot of a screen that could not say whether
618	              anything was happening at all. */}
619	          {replaying ? (
620	            <p className="map-origin__line">
621	              {replaySentence({
622	                recordingDate: growth.receipt?.recording_date ?? null,
623	                receiptMode: growth.receipt?.mode ?? null,
624	              })}
625	            </p>
626	          ) : null}
627	          {(growth.world.warnings ?? []).map((warning) => (
628	            <p className="map-origin__line" key={warning}>
629	              {warning}
630	            </p>
631	          ))}
632	        </>
633	      }
634	    />
635	  );
636	}
